<script lang="ts">
	import { Check, CircleDot, KeyRound, Pencil, Plus, RefreshCw, Shield, Trash2, Upload, X } from '@lucide/svelte';
	import { onMount } from 'svelte';
	import {
		createEvnVpnController, deleteEvnVpnController, disableOpenvpn, enableOpenvpn, getEvnVpnControllers,
		getOpenvpnStatus, getVpnChannelStatus, pingIpsec, saveOpenvpnConfig, updateEvnVpnController, uploadOpenvpnProfile
	} from '$lib/services/rts-api';

	type IpsecForm = { id:string;alias:string;enabled:boolean;localId:string;localSubnet:string;natLeft:boolean;remotePublicIp:string;remoteId:string;remoteSubnet:string;psk:string };
	type Controller = IpsecForm & { 'service.pid':string; phase1Status?:unknown; phase2Status?:unknown; errorDetails?:unknown };
	const initial=():IpsecForm=>({id:'EVNNPC0',alias:'',enabled:false,localId:'AT_Energy',localSubnet:'10.0.0.0/24',natLeft:true,remotePublicIp:'116.212.47.2',remoteId:'Sophos_EVN',remoteSubnet:'10.21.10.64/27',psk:''});
	let tab=$state<'ipsec'|'openvpn'>('ipsec');
	let controllers=$state<Controller[]>([]);
	let dialogOpen=$state(false);
	let editing=$state<Controller|null>(null);
	let form=$state<IpsecForm>(initial());
	let loading=$state(false);let saving=$state(false);let error=$state('');let notice=$state('');let pingResult=$state('');
	let openvpn=$state({status:'Disabled',description:'',username:'',password:''});
	let openvpnRuntime=$state<any>({status:'UNKNOWN'});let profileFile=$state<File|null>(null);

	onMount(()=>{void loadIpsec();void loadOpenvpn();const timer=setInterval(()=>{if(tab==='openvpn')void loadOpenvpn();},5000);return()=>clearInterval(timer)});
	async function loadIpsec(){loading=true;error='';try{const raw=await getEvnVpnControllers() as any[];controllers=await Promise.all(raw.map(async(item)=>({...initial(),...item,...await getVpnChannelStatus(String(item.id??item.pid??'EVNNPC0'))})));}catch(cause){error=cause instanceof Error?cause.message:'Unable to load IPsec controllers.';}finally{loading=false;}}
	async function loadOpenvpn(){try{openvpnRuntime=await getOpenvpnStatus();const status=String(openvpnRuntime?.status??openvpnRuntime?.state??'Disabled');openvpn.status=status.toLowerCase().includes('enable')||status.toLowerCase().includes('connect')?'Enabled':'Disabled';}catch(cause){if(tab==='openvpn')error=cause instanceof Error?cause.message:'Unable to load OpenVPN status.';}}
	function nextId(){let index=0;while(controllers.some((item)=>item.id===`EVNNPC${index}`))index++;return `EVNNPC${index}`}
	function openAdd(){editing=null;form={...initial(),id:nextId()};error='';notice='';dialogOpen=true}
	function openEdit(item:Controller){editing=item;form={id:item.id,alias:item.alias,enabled:item.enabled===true,localId:item.localId,localSubnet:item.localSubnet,natLeft:item.natLeft===true,remotePublicIp:item.remotePublicIp,remoteId:item.remoteId,remoteSubnet:item.remoteSubnet,psk:item.psk};error='';dialogOpen=true}
	function validate(){if(!form.id.trim())return'Enter a controller ID.';if(!form.localId.trim()||!form.remoteId.trim())return'Local ID and Remote ID are required.';if(!form.localSubnet.trim()||!form.remoteSubnet.trim())return'Local and Remote subnet are required.';if(!form.remotePublicIp.trim())return'Enter the remote public IP.';if(!form.psk)return'Enter the pre-shared key.';return''}
	async function saveIpsec(){error=validate();if(error)return;saving=true;try{if(form.enabled){await Promise.all(controllers.filter((item)=>item.enabled&&item['service.pid']!==editing?.['service.pid']).map((item)=>updateEvnVpnController(item['service.pid'],{...item,enabled:false})));}if(editing)await updateEvnVpnController(editing['service.pid'],form);else await createEvnVpnController(form);dialogOpen=false;notice='IPsec controller saved successfully.';await loadIpsec();}catch(cause){error=cause instanceof Error?cause.message:'Unable to save IPsec controller.';}finally{saving=false;}}
	async function remove(item:Controller){if(!confirm(`Delete ${item.alias||item.id}?`))return;try{await deleteEvnVpnController(item['service.pid']);notice=`${item.alias||item.id} deleted.`;await loadIpsec();}catch(cause){error=cause instanceof Error?cause.message:'Unable to delete IPsec controller.';}}
	async function ping(item:Controller){pingResult='Pinging…';try{const response=await pingIpsec(item.remotePublicIp);pingResult=String(response?.result??response?.message??'Ping request completed.');}catch(cause){pingResult=cause instanceof Error?cause.message:'Ping failed.';}}
	function chooseFile(event:Event){profileFile=(event.currentTarget as HTMLInputElement).files?.[0]??null}
	async function saveOpenvpn(){saving=true;error='';try{if(profileFile)await uploadOpenvpnProfile(profileFile);await saveOpenvpnConfig({status:openvpn.status,description:openvpn.description,username:openvpn.username,password:openvpn.password});if(openvpn.status==='Enabled')await enableOpenvpn();else await disableOpenvpn();notice='OpenVPN configuration saved successfully.';await loadOpenvpn();}catch(cause){error=cause instanceof Error?cause.message:'Unable to save OpenVPN configuration.';}finally{saving=false;}}
</script>

<section class="page"><div class="head"><div><h2>VPN</h2><p>RTS secure remote connection using the existing IPsec and OpenVPN services.</p></div>{#if tab==='ipsec'}<div class="head-actions"><button class:loading class="refresh" type="button" aria-label="Refresh IPsec connections" disabled={loading} onclick={loadIpsec}><RefreshCw size={17}/></button><button class="primary" onclick={openAdd}><Plus size={17}/>Add IPsec</button></div>{/if}</div>
	<div class="tabs"><button class:active={tab==='ipsec'} onclick={()=>tab='ipsec'}>IPsec Site-to-Site</button><button class:active={tab==='openvpn'} onclick={()=>tab='openvpn'}>OpenVPN</button></div>
	{#if notice}<div class="notice"><Check size={16}/>{notice}</div>{/if}{#if error&&!dialogOpen}<div class="request-error">{error}</div>{/if}
	{#if tab==='ipsec'}<div class="table"><table><thead><tr><th>Connection</th><th>Local network</th><th>Remote gateway</th><th>Phase 1</th><th>Phase 2</th><th></th></tr></thead><tbody>{#if controllers.length===0}<tr><td class="empty" colspan="6"><Shield size={27}/><strong>No IPsec connections configured</strong><span>Add the first EVN VPN controller.</span></td></tr>{:else}{#each controllers as item}<tr><td><strong>{item.alias||item.id}</strong><small>{item.id} · {item.enabled?'Enabled':'Disabled'}</small></td><td>{item.localSubnet}</td><td><strong>{item.remotePublicIp}</strong><small>{item.remoteSubnet}</small></td><td><span class="state">{String(item.phase1Status??'Unknown')}</span></td><td><span class="state">{String(item.phase2Status??'Unknown')}</span></td><td class="actions"><button onclick={()=>ping(item)} aria-label="Ping"><CircleDot size={16}/></button><button onclick={()=>openEdit(item)} aria-label="Edit"><Pencil size={16}/></button><button class="delete" onclick={()=>remove(item)} aria-label="Delete"><Trash2 size={16}/></button></td></tr>{/each}{/if}</tbody></table></div>{#if pingResult}<div class="ping-result">{pingResult}</div>{/if}
	{:else}<div class="openvpn-grid"><section class="card"><header><span><Shield size={20}/></span><div><h3>OpenVPN status</h3><p>Updated every 5 seconds</p></div><em>{String(openvpnRuntime?.status??'UNKNOWN')}</em></header><div class="status-grid"><div><span>Connection</span><strong>{String(openvpnRuntime?.connection??openvpnRuntime?.state??openvpnRuntime?.status??'Unknown')}</strong></div><div><span>Remote IP</span><strong>{String(openvpnRuntime?.remoteIp??openvpnRuntime?.ipAddress??'—')}</strong></div><div><span>Last error</span><strong>{String(openvpnRuntime?.error??openvpnRuntime?.lastError??'None')}</strong></div></div></section><section class="card"><header><span><KeyRound size={20}/></span><div><h3>OpenVPN configuration</h3><p>Profile and credentials</p></div></header><div class="form"><label>Status<div class="toggle"><button class:active={openvpn.status==='Enabled'} onclick={()=>openvpn.status='Enabled'}>Enabled</button><button class:active={openvpn.status==='Disabled'} onclick={()=>openvpn.status='Disabled'}>Disabled</button></div></label><label>Description<input bind:value={openvpn.description} placeholder="Optional description"/></label><label>Username<input bind:value={openvpn.username} autocomplete="username"/></label><label>Password<input type="password" bind:value={openvpn.password} autocomplete="current-password"/></label><label class="file"><span>OpenVPN profile</span><input type="file" accept=".ovpn,.conf" onchange={chooseFile}/><i><Upload size={16}/>{profileFile?.name??'Choose .ovpn file'}</i></label></div><footer><button class="primary" disabled={saving} onclick={saveOpenvpn}>{saving?'Saving…':'Save OpenVPN'}</button></footer></section></div>{/if}
</section>

{#if dialogOpen}<div class="backdrop" onclick={()=>dialogOpen=false} role="presentation"><dialog open onclick={(event)=>event.stopPropagation()}><header><div><h3>{editing?'Edit':'Add'} IPsec connection</h3><p>Controller.VPN.EVN</p></div><button onclick={()=>dialogOpen=false} aria-label="Close"><X size={19}/></button></header><form onsubmit={(event)=>{event.preventDefault();void saveIpsec();}}><div class="body"><section><h4>Connection</h4><div class="grid"><label>Controller ID<input bind:value={form.id} disabled={!!editing}/></label><label>Alias<input bind:value={form.alias}/></label><label class="check"><input type="checkbox" bind:checked={form.enabled}/>Enabled</label><label class="check"><input type="checkbox" bind:checked={form.natLeft}/>NAT left</label></div></section><section><h4>Local endpoint</h4><div class="grid"><label>Local ID<input bind:value={form.localId}/></label><label>Local subnet<input bind:value={form.localSubnet}/></label></div></section><section><h4>Remote endpoint</h4><div class="grid"><label>Remote public IP<input bind:value={form.remotePublicIp}/></label><label>Remote ID<input bind:value={form.remoteId}/></label><label>Remote subnet<input bind:value={form.remoteSubnet}/></label><label>Pre-shared key<input type="password" bind:value={form.psk}/></label></div></section>{#if error}<p class="error">{error}</p>{/if}</div><footer><button class="secondary" type="button" onclick={()=>dialogOpen=false}>Cancel</button><button class="primary" type="submit" disabled={saving}>{saving?'Saving…':'Save IPsec'}</button></footer></form></dialog></div>{/if}

<style>
	.page{animation:in .18s ease}.head{display:flex;align-items:flex-start;justify-content:space-between;gap:18px;margin-bottom:18px}.head h2{margin:0;color:#172b4d;font-size:24px;font-weight:500}.head p{margin:7px 0 0;color:#718096;font-size:16px}.primary,.secondary{display:inline-flex;align-items:center;justify-content:center;gap:7px;min-height:38px;padding:0 13px;border-radius:8px;font:inherit;cursor:pointer}.primary{border:0;color:#fff;background:#1749ad}.secondary{border:1px solid #d8e0eb;color:#43536e;background:#fff}.tabs{display:flex;gap:5px;border-bottom:1px solid #e2e8f1}.tabs button{height:41px;padding:0 14px;border:0;border-bottom:2px solid transparent;color:#65738b;background:transparent;font:inherit;cursor:pointer}.tabs button.active{border-color:#2454b6;color:#1d4ba7}.notice,.request-error,.ping-result{margin:13px 0 0;padding:10px 12px;border-radius:8px;font-size:13px}.notice{display:flex;align-items:center;gap:7px;border:1px solid #cae7d5;color:#28784e;background:#f2fbf5}.request-error{border:1px solid #f3cac6;color:#b42318;background:#fff1f0}.ping-result{color:#415271;background:#eef3fb}.table{margin-top:15px;overflow-x:auto;border-top:1px solid #e5ebf3;border-bottom:1px solid #e5ebf3;background:#fff}.table table{width:100%;min-width:900px;border-collapse:collapse}th,td{padding:13px 16px;border-bottom:1px solid #edf1f6;color:#526179;font-size:14px;text-align:left}th{color:#79869a;background:#f8faff;font-size:11px;font-weight:500;text-transform:uppercase}td strong,td small{display:block}td strong{color:#34445e;font-weight:500}td small{margin-top:3px;color:#8994a6;font-size:12px}.state{padding:5px 8px;border-radius:12px;color:#46618d;background:#eef3fb;font-size:12px}.actions{display:flex;justify-content:flex-end;gap:6px}.actions button{display:grid;place-items:center;width:32px;height:32px;border:1px solid #dce6fb;border-radius:7px;color:#31569f;background:#f6f9ff;cursor:pointer}.actions .delete{color:#c72f25;background:#fff7f6;border-color:#f2d7d4}.empty{height:250px;text-align:center}.empty :global(svg),.empty strong,.empty span{display:block;margin:auto}.empty :global(svg){margin-bottom:10px;color:#6d8bd1}.empty span{margin-top:6px;color:#7c889d}.openvpn-grid{display:grid;grid-template-columns:.8fr 1.2fr;gap:15px;margin-top:15px}.card{overflow:hidden;border:1px solid #e1e7f0;border-radius:11px;background:#fff}.card>header{display:flex;align-items:center;gap:10px;padding:16px 18px;border-bottom:1px solid #edf0f4}.card>header>span{display:grid;place-items:center;width:35px;height:35px;border-radius:9px;color:#2754b5;background:#eaf0ff}.card h3{margin:0;color:#31415c;font-size:16px;font-weight:500}.card header p{margin:4px 0 0;color:#8792a4;font-size:12px}.card header em{margin-left:auto;color:#27764d;font-size:12px;font-style:normal}.status-grid{display:grid;gap:9px;padding:17px}.status-grid div{padding:12px;border-radius:8px;background:#f7f9fc}.status-grid span,.status-grid strong{display:block}.status-grid span{color:#8792a4;font-size:11px}.status-grid strong{margin-top:5px;color:#34445e;font-weight:500}.form{display:grid;grid-template-columns:1fr 1fr;gap:13px;padding:17px}.form label,.grid label{display:grid;gap:6px;color:#536078;font-size:13px}.form input,.grid input{width:100%;height:38px;padding:0 10px;border:1px solid #d7dfeb;border-radius:7px;color:#273853;background:#fff;font:inherit}.toggle{display:flex;height:38px;padding:3px;border-radius:8px;background:#edf1f7}.toggle button{flex:1;border:0;border-radius:6px;color:#68768c;background:transparent;font:inherit}.toggle button.active{color:#1749ad;background:#fff}.file input{position:absolute;opacity:0;pointer-events:none}.file i{display:flex;align-items:center;gap:7px;height:38px;padding:0 10px;border:1px dashed #bfcce0;border-radius:7px;color:#566a8d;font-style:normal;cursor:pointer}.card>footer{display:flex;justify-content:flex-end;padding:12px 17px;border-top:1px solid #edf0f4}.backdrop{position:fixed;inset:0;z-index:30;display:grid;place-items:center;padding:12px;background:rgba(24,35,58,.25)}dialog{display:flex;flex-direction:column;width:min(560px,calc(100% - 24px));max-height:calc(100vh - 24px);margin:0;padding:0;overflow:hidden;border:1px solid #e1e6ee;border-radius:12px;background:#fff}dialog>header{display:flex;justify-content:space-between;padding:16px 20px 13px;border-bottom:1px solid #edf0f4}dialog h3{margin:0;color:#1d304f;font-size:19px;font-weight:500}dialog header p{margin:4px 0 0;color:#77849a;font-size:12px}dialog header button{border:0;color:#65728a;background:transparent}dialog form{display:flex;min-height:0;flex:1;flex-direction:column}.body{padding:16px 20px;overflow:auto}.body section+section{margin-top:16px}.body h4{margin:0 0 10px;color:#31415c;font-size:14px;font-weight:500}.grid{display:grid;grid-template-columns:1fr 1fr;gap:11px 13px}.check{display:flex!important;align-items:center;align-self:end;height:38px}.check input{width:16px;height:16px;accent-color:#1749ad}.error{color:#b42318;font-size:13px}dialog footer{display:flex;justify-content:flex-end;gap:8px;padding:11px 20px;border-top:1px solid #edf0f4}.spin{animation:spin .8s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}@keyframes in{from{opacity:0;transform:translateY(4px)}}@media(max-width:950px){.openvpn-grid{grid-template-columns:1fr}}@media(max-width:650px){.head{flex-direction:column}.head .primary{width:100%}.form,.grid{grid-template-columns:1fr}}
	.head-actions{display:flex;align-items:center;gap:8px}.refresh{display:grid;width:38px;height:38px;place-items:center;border:1px solid #d8e0eb;border-radius:8px;color:#43536e;background:#fff;cursor:pointer}.refresh.loading :global(svg){animation:spin .8s linear infinite}.refresh:disabled{cursor:wait;opacity:.72}.empty{height:330px}
	dialog{position:relative}
	@media(max-width:650px){.head-actions{width:100%}.head-actions .primary{flex:1}}
</style>
